        S.el('rect', { x: X0, y: fs.ceiling, width: X1 - X0, height: Y1 - fs.ceiling, class: 'f-paper-2' }, G);
        S.el('line', { x1: X0, y1: fs.ceiling, x2: X1, y2: fs.ceiling, class: 'ln-cut' }, G);
        S.windowEl(G, 430, roof.ceiling + 46, 220, 150, .9);
        // 흐트러진 물건(사람마다 다른 최종 배치)
        S.ball(G, 236, floor - 28, 28, 40);
        const ch = S.g(G, { transform: `translate(820 ${floor - 38}) rotate(-78)` }); S.chair(ch, 0, 0, 1.25);
        S.cup(G, 600, floor - 18, 1.25, 92);
        S.lamp(G, 520, fs.ceiling, 50, 4, { scale: .9, cone: 60 });
